/// </summary>
public sealed class DuckDbProjectDatabase(JetProjectFolder folder) : ILocalProjectDatabase, IProjectDatabaseRetention
{
    /// <summary>DuckDB 資料庫檔名（與 sqlite 的 jet.db 並列於同一 projects/{id}/ 資料夾）。</summary>
